from math import copysign

def soft_threshold(value, penalty):
    if penalty < 0:
        raise ValueError("Penalty must be nonnegative")
    # Remove the penalty magnitude, stop at zero, then restore the sign.
    return copysign(max(abs(value) - penalty, 0.0), value)

for value in [0.2, 2.0]:
    print(round(soft_threshold(value, 0.5), 6), round(value / 1.5, 6))

