def predict(features, weights, bias):
    if len(features) != len(weights):
        raise ValueError("Feature/weight dimensions must match")
    return bias + sum(x * w for x, w in zip(features, weights))


print(predict([1500, 3], [0.04, 5], 8))  # 83.0

def predict(x):
    return 1 + 2 * x + 0.5 * x * x


print(predict(3))  # 11.5
